      {
        "letra": "c",
        "texto": "La Mutua es responsable del pago sin posibilidad de resarcimiento posterior."
      },
      {
        "letra": "d",
        "texto": "La Mutua Colaboradora con la Seguridad Social está obligada al anticipo del pago de la prestación."
      }
