    "tema": "TEMA V. PREVENCIÓN DE RIESGOS LABORALES SPP",
    "pregunta": "427. COMPETENCIAS DE LOS DELEGADOS DE PREVENCIÓN",
    "opciones": [
      {
        "letra": "a",
        "texto": "Ser consultados por el empresario, con carácter previo a su ejecución, acerca de las decisiones a que se refiere el art. 33 LPRL: como Planificación y organización del trabajo en la empresa y la introducción de nuevas tecnologías; Organización y desarrollo de las actividades de protección de la salud y prevención de los riesgos profesionales en la empresa. O designación de los trabajadores encargados de las medidas de emergencia entre otros."
      },
      {
        "letra": "b",
        "texto": "Colaborar con la dirección de empresa en la mejora de la acción preventiva: Los delegados de prevención tienen el derecho, pero también el deber, de colaborar tanto con el empresario, como con los mandos intermedios para incluir mejoras en la acción preventiva."
      },
      {
        "letra": "c",
        "texto": "Promover y fomentar la cooperación de los trabajadores en la ejecución de la normativa sobre prevención de riesgos laborales"
      },
      {
        "letra": "d",
        "texto": "Todas son correctas."
      }
    ],
    "respuestaCorrecta": "d"
